"""Stock levels, status, buying advice, history and fulfilment availability."""


def stock_levels(catalog, movements):
    """Return a dict of SKU -> quantity on the shelf for every product."""
    levels = {sku: 0 for sku in sorted(catalog)}
    for move in movements:
        if move.sku in levels:
            levels[move.sku] += move.quantity
    return levels


def stock_status(onhand, reorder):
    if onhand == 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def buy_quantity(onhand, reorder):
    return max(1, 2 * reorder - onhand)


def counting_order(movements):
    """Movements in the order they count: by date, file order within a day."""
    return sorted(movements, key=lambda move: move.date)


def first_below_zero(movements):
    """Index (in the given list) of the movement that first takes a product
    below zero in counting order, or ``None``."""
    order = sorted(range(len(movements)), key=lambda i: movements[i].date)
    balance = {}
    for index in order:
        move = movements[index]
        after = balance.get(move.sku, 0) + move.quantity
        if after < 0:
            return index
        balance[move.sku] = after
    return None


def history(movements, sku):
    """List of ``(movement, balance_after)`` for one SKU in counting order."""
    rows = []
    balance = 0
    for move in counting_order(movements):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows


def available_on(movements, sku, day):
    """Most that can be shipped on ``day`` without breaking a later movement."""
    balance = 0
    lowest = None
    for move in counting_order(movements):
        if move.sku != sku:
            continue
        balance += move.quantity
        if move.date <= day:
            lowest = balance
        else:
            lowest = min(lowest if lowest is not None else 0, balance)
    return max(0, lowest if lowest is not None else 0)


def shipped_so_far(movements, order_id, sku, ordered):
    """Units of ``sku`` already shipped for the order, capped at ``ordered``."""
    note = "order " + order_id
    out = sum(
        -move.quantity
        for move in movements
        if move.sku == sku and move.note == note and move.quantity < 0
    )
    return min(ordered, out)
