        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows


def available_on(movements, sku, day):
    """Most that can be shipped on ``day`` without breaking a later movement."""
    balance = 0
    lowest = None
    for move in counting_order(movements):
        if move.sku != sku:
            continue
        balance += move.quantity
        if move.date <= day:
            lowest = balance
        else:
            lowest = min(lowest if lowest is not None else 0, balance)
    return max(0, lowest if lowest is not None else 0)


def shipped_so_far(movements, order_id, sku, ordered):
    """Units of ``sku`` already shipped for the order, capped at ``ordered``."""
    note = "order " + order_id
    out = sum(
        -move.quantity
        for move in movements
        if move.sku == sku and move.note == note and move.quantity < 0
    )
    return min(ordered, out)
