"""Exact-to-the-penny order pricing."""

from decimal import ROUND_HALF_UP, Context, Decimal, localcontext

from .models import Quote, QuoteLine

_CENT = Decimal("0.01")
_ZERO = Decimal("0.00")
_CTX = Context(prec=2000, rounding=ROUND_HALF_UP, Emax=999999, Emin=-999999)
_TAX_RATES = {
    "standard": Decimal("0.20"),
    "reduced": Decimal("0.05"),
    "zero": Decimal("0"),
}
_ORDER_DISCOUNT_FROM = Decimal("500.00")
_ORDER_DISCOUNT_RATE = Decimal("0.03")


def _penny(value):
    return value.quantize(_CENT, rounding=ROUND_HALF_UP)


def _discount(amount, rate):
    """A negative (or zero) discount of ``rate`` of ``amount``, to the penny."""
    cut = _penny(amount * rate)
    return -cut if cut else _ZERO


def _volume_rate(quantity):
    if quantity >= 50:
        return Decimal("0.10")
    if quantity >= 10:
        return Decimal("0.05")
    return Decimal("0")


def _shares(total_pennies, nets):
    """Share ``total_pennies`` over ``nets`` (in pennies) in proportion, to the
    penny: floor shares, leftovers to the biggest lost fractions, earlier first."""
    whole = sum(nets)
    shares = []
    lost = []
    for net in nets:
        product = total_pennies * net
        shares.append(product // whole)
        lost.append(product % whole)
    leftover = total_pennies - sum(shares)
    by_loss = sorted(range(len(nets)), key=lambda i: (-lost[i], i))
    for index in by_loss[:leftover]:
        shares[index] += 1
    return shares


def price_order(order, catalog):
    """Price a whole order and return a :class:`Quote`."""
    with localcontext(_CTX):
        lines = []
        for sku, quantity in order.lines:
            unit = catalog[sku].price
            gross = _penny(unit * quantity)
            discount = _discount(gross, _volume_rate(quantity))
            lines.append(QuoteLine(sku, quantity, _penny(unit), gross, discount, gross + discount))
        subtotal = _penny(sum((line.net for line in lines), _ZERO))
        if subtotal >= _ORDER_DISCOUNT_FROM:
            order_discount = _discount(subtotal, _ORDER_DISCOUNT_RATE)
        else:
            order_discount = _ZERO
        nets = [int(line.net * 100) for line in lines]
        pennies = int(-order_discount * 100)
        shares = _shares(pennies, nets) if lines and pennies else [0] * len(lines)
        tax = _ZERO
        for line, share in zip(lines, shares):
            taxable = line.net - Decimal(share).scaleb(-2)
            tax += _penny(taxable * _TAX_RATES[catalog[line.sku].tax])
        tax = _penny(tax)
        total = _penny(subtotal + order_discount + tax)
        return Quote(lines, subtotal, order_discount, tax, total)
