"""Parsers for catalog.txt, movements.txt and orders.txt."""

import re
from datetime import date
from decimal import Decimal

from .errors import ParseError
from .models import Movement, Order, Product
from .shelves import first_below_zero

WS = " \t"

TAX_RATES = ("standard", "reduced", "zero")

_SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_PRICE_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
_DIGITS_RE = re.compile(r"[0-9]+")
_QUANTITY_RE = re.compile(r"[+-]?[0-9]+")
_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+")
_MOVEMENT_RE = re.compile(
    r"[ \t]*([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(.*)", re.DOTALL
)
_FIELD_SPLIT_RE = re.compile(r"[ \t]+")
_MIN_PRICE = Decimal("0.01")


def iter_lines(text):
    """Yield ``(line_number, line)`` for every line that carries data."""
    if text.startswith("\ufeff"):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        body = raw.strip(WS)
        if not body or body.startswith("#"):
            continue
        yield number, raw


def parse_date(text):
    """Return a ``datetime.date`` for ``YYYY-MM-DD`` text, else ``None``."""
    match = _DATE_RE.fullmatch(text)
    if not match:
        return None
    try:
        return date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    except ValueError:
        return None


def _whole_number(number, text, what):
    try:
        return int(text)
    except ValueError:  # absurdly long digit strings
        raise ParseError(number, "%s %r is too large" % (what, text[:20]))


def _sku(number, text, catalog):
    if not _SKU_RE.fullmatch(text) or text.upper() not in catalog:
        raise ParseError(number, "unknown SKU %r" % text)
    return text.upper()


def _date(number, text):
    day = parse_date(text)
    if day is None:
        raise ParseError(number, "bad date %r (want a real YYYY-MM-DD date)" % text)
    return day


def parse_catalog(text):
    """Parse catalog.txt text into a dict of SKU -> :class:`Product`."""
    catalog = {}
    first_seen = {}
    for number, raw in iter_lines(text):
        fields = [field.strip(WS) for field in raw.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                number,
                "expected 4 or 5 fields separated by '|', found %d" % len(fields),
            )
        sku_text, name, price_text, reorder_text = fields[:4]
        tax = fields[4].lower() if len(fields) == 5 else "standard"
        if not _SKU_RE.fullmatch(sku_text):
            raise ParseError(number, "bad SKU %r (want letters-digits like AB-100)" % sku_text)
        sku = sku_text.upper()
        if sku in catalog:
            raise ParseError(
                number, "duplicate SKU %s (first on line %d)" % (sku, first_seen[sku])
            )
        if not name:
            raise ParseError(number, "name is empty")
        if not _PRICE_RE.fullmatch(price_text) or Decimal(price_text) < _MIN_PRICE:
            raise ParseError(
                number, "bad price %r (want at least 0.01, at most two decimals)" % price_text
            )
        if "." not in price_text:
            price_text += ".00"
        elif len(price_text.split(".")[1]) == 1:
            price_text += "0"
        if not _DIGITS_RE.fullmatch(reorder_text):
            raise ParseError(number, "bad reorder level %r (want a whole number)" % reorder_text)
        reorder = _whole_number(number, reorder_text, "reorder level")
        if tax not in TAX_RATES:
            raise ParseError(
                number, "bad tax %r (want standard, reduced or zero)" % fields[4]
            )
        first_seen[sku] = number
        catalog[sku] = Product(sku, name, Decimal(price_text), reorder, tax)
    return catalog


def parse_movements(text, catalog):
    """Parse movements.txt text into a list of :class:`Movement` in file order."""
    movements = []
    numbers = []
    for number, raw in iter_lines(text):
        match = _MOVEMENT_RE.fullmatch(raw)
        if not match:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date_text, sku_text, quantity_text, rest = match.groups()
        day = _date(number, date_text)
        sku = _sku(number, sku_text, catalog)
        if not _QUANTITY_RE.fullmatch(quantity_text):
            raise ParseError(number, "bad quantity %r (want a whole number)" % quantity_text)
        quantity = _whole_number(number, quantity_text, "quantity")
        if quantity == 0:
            raise ParseError(number, "quantity may not be zero")
        movements.append(Movement(day, sku, quantity, rest.strip(WS)))
        numbers.append(number)
    bad = first_below_zero(movements)
    if bad is not None:
        move = movements[bad]
        raise ParseError(
            numbers[bad],
            "stock of %s would go below zero on %s" % (move.sku, move.date.isoformat()),
        )
    return movements


def parse_orders(text, catalog):
    """Parse orders.txt text into a list of :class:`Order` in file order."""
    orders = []
    first_seen = {}
    for number, raw in iter_lines(text):
        tokens = _FIELD_SPLIT_RE.split(raw.strip(WS))
        if len(tokens) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES")
        id_text, date_text, customer, lines_text = tokens
        if not _ORDER_ID_RE.fullmatch(id_text):
            raise ParseError(number, "bad order number %r (want SO-1234)" % id_text)
        order_id = id_text.upper()
        if order_id in first_seen:
            raise ParseError(
                number,
                "duplicate order %s (first on line %d)" % (order_id, first_seen[order_id]),
            )
        day = _date(number, date_text)
        lines = []
        seen = set()
        for item in lines_text.split(","):
            parts = item.split("*")
            if len(parts) != 2:
                raise ParseError(number, "bad order line %r (want SKU*QUANTITY)" % item)
            sku = _sku(number, parts[0], catalog)
            if sku in seen:
                raise ParseError(number, "SKU %s appears twice in the order" % sku)
            if not _DIGITS_RE.fullmatch(parts[1]):
                raise ParseError(number, "bad quantity %r (want a whole number)" % parts[1])
            quantity = _whole_number(number, parts[1], "quantity")
            if quantity < 1:
                raise ParseError(number, "quantity must be at least 1")
            seen.add(sku)
            lines.append((sku, quantity))
        first_seen[order_id] = number
        orders.append(Order(order_id, day, customer, lines))
    return orders
EOF
