"""The ``stockroom`` command line."""

import csv
import io
import json
import os
import re
import sys

from .errors import ParseError
from .fulfilment import order_status, plan_fulfilment, shipped_order
from .models import Movement
from .parsing import WS, parse_catalog, parse_date, parse_movements, parse_orders
from .pricing import price_order
from .shelves import (
    buy_quantity,
    first_below_zero,
    history,
    shipped_so_far,
    stock_levels,
    stock_status,
)

USAGE = """\
usage: stockroom [--dir DIR] COMMAND [ARGUMENT ...]

commands:
  stock [--json]                       what is on the shelves
  low [--json]                         what needs buying
  history SKU [--json]                 one product's movements
  receive DATE SKU QUANTITY [NOTE]     record stock in
  ship DATE SKU QUANTITY [NOTE]        record stock out
  quote ORDER [--json]                 price an order
  fulfil ORDER DATE                    ship what the shelves can cover
  invoice ORDER [--json]               price what has shipped
  report [--format text|csv|json]      one row per order

--dir DIR (anywhere on the line) names the folder holding catalog.txt,
movements.txt and orders.txt; the default is the current folder.
"""

# command -> (number of positional arguments allowed, takes --json)
_COMMANDS = {
    "stock": ((0, 0), True),
    "low": ((0, 0), True),
    "history": ((1, 1), True),
    "receive": ((3, 4), False),
    "ship": ((3, 4), False),
    "quote": ((1, 1), True),
    "fulfil": ((2, 2), False),
    "invoice": ((1, 1), True),
    "report": ((0, 0), False),
}
_FREE_FORM = ("receive", "ship", "fulfil")
_NEEDS_ORDERS = ("quote", "fulfil", "invoice", "report")
_NEEDS_MOVEMENTS = ("stock", "low", "history", "receive", "ship", "fulfil", "invoice", "report")
_FORMATS = ("text", "csv", "json")
_DIGITS_RE = re.compile(r"[0-9]+")


class _Exit(Exception):
    """Stop with an exit status and a message for standard error."""

    def __init__(self, code, message):
        super().__init__(message)
        self.code = code
        self.message = message


def _usage_error(message):
    return _Exit(2, "stockroom: %s (try 'stockroom --help')" % message)


def _refused(message):
    return _Exit(1, "stockroom: %s" % message)


# ---------------------------------------------------------------- command line


class _Request:
    def __init__(self):
        self.dir = "."
        self.command = None
        self.args = []
        self.json = False
        self.format = "text"
        self.help = False


def _parse_command_line(argv):
    request = _Request()
    rest = []
    index = 0
    while index < len(argv):
        arg = argv[index]
        if arg == "--dir":
            if index + 1 >= len(argv):
                raise _usage_error("option --dir needs a folder")
            request.dir = argv[index + 1]
            index += 2
            continue
        if arg.startswith("--dir="):
            request.dir = arg[len("--dir="):]
            index += 1
            continue
        rest.append(arg)
        index += 1
    if request.dir == "":
        raise _usage_error("option --dir needs a folder")
    if not rest:
        raise _usage_error("no command given")
    command = rest[0]
    if command in ("-h", "--help"):
        request.help = True
        return request
    if command not in _COMMANDS:
        if command.startswith("-") and len(command) > 1:
            raise _usage_error("unknown option %s" % command)
        raise _usage_error("unknown command %s" % command)
    request.command = command
    (low, high), takes_json = _COMMANDS[command]
    if command in _FREE_FORM:
        request.args = rest[1:]
    else:
        args = rest[1:]
        position = 0
        while position < len(args):
            arg = args[position]
            position += 1
            if arg in ("-h", "--help"):
                request.help = True
                return request
            if takes_json and arg == "--json":
                request.json = True
            elif command == "report" and arg == "--format":
                if position >= len(args):
                    raise _usage_error("option --format needs a value")
                request.format = args[position]
                position += 1
            elif command == "report" and arg.startswith("--format="):
                request.format = arg[len("--format="):]
            elif arg.startswith("-") and len(arg) > 1:
                raise _usage_error("unknown option %s" % arg)
            else:
                request.args.append(arg)
        if request.format not in _FORMATS:
            raise _usage_error("bad --format value %r (want text, csv or json)" % request.format)
    if not low <= len(request.args) <= high:
        raise _usage_error("wrong number of arguments for %s" % command)
    date_at = {"receive": 0, "ship": 0, "fulfil": 1}.get(command)
    if date_at is not None and parse_date(request.args[date_at]) is None:
        raise _usage_error("bad date %r (want a real YYYY-MM-DD date)" % request.args[date_at])
    return request


# ----------------------------------------------------------------------- files


def _read(folder, name, required):
    path = os.path.join(folder, name)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise _Exit(2, "%s: file not found in %s" % (name, folder))
        return ""
    except OSError as error:
        raise _Exit(2, "%s: cannot read: %s" % (name, error.strerror or error))
    try:
        return data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise _Exit(2, "%s: not valid UTF-8" % name)


def _parse(name, function, *args):
    try:
        return function(*args)
    except ParseError as error:
        raise _Exit(1, "%s: %s" % (name, error))


class _Data:
    pass


def _load(request):
    command = request.command
    if not os.path.isdir(request.dir):
        raise _Exit(2, "%s: not a folder" % request.dir)
    texts = {"catalog.txt": _read(request.dir, "catalog.txt", True)}
    if command in _NEEDS_MOVEMENTS:
        texts["movements.txt"] = _read(request.dir, "movements.txt", False)
    if command in _NEEDS_ORDERS:
        texts["orders.txt"] = _read(request.dir, "orders.txt", False)
    data = _Data()
    data.dir = request.dir
    data.catalog = _parse("catalog.txt", parse_catalog, texts["catalog.txt"])
    data.movements = None
    data.orders = None
    if "movements.txt" in texts:
        data.movements = _parse(
            "movements.txt", parse_movements, texts["movements.txt"], data.catalog
        )
        data.movements_text = texts["movements.txt"]
    if "orders.txt" in texts:
        data.orders = _parse("orders.txt", parse_orders, texts["orders.txt"], data.catalog)
