                "quoted": _money(quoted),
                "invoiced": _money(invoiced) if invoiced is not None else "0.00",
            }
        )
    if request.format == "json":
        return _dump(rows)
    if request.format == "csv":
        buffer = io.StringIO()
        writer = csv.DictWriter(
            buffer,
            fieldnames=[
                "order", "date", "customer", "status",
                "ordered", "shipped", "quoted", "invoiced",
            ],
            lineterminator="\n",
        )
        writer.writeheader()
        writer.writerows(rows)
        return buffer.getvalue()
    return _lines(
        "%(order)s %(date)s %(customer)s %(status)s %(shipped)d/%(ordered)d "
        "%(quoted)s %(invoiced)s" % row
        for row in rows
    )


_HANDLERS = {
    "stock": _stock,
    "low": _low,
    "history": _history,
    "receive": _record,
    "ship": _record,
    "quote": _quote,
    "fulfil": _fulfil,
    "invoice": _invoice,
    "report": _report,
}


# ------------------------------------------------------------------------ main


def _run(argv):
    request = _parse_command_line(argv)
    if request.help:
        return USAGE
    data = _load(request)
    return _HANDLERS[request.command](request, data)


def _quiet_stdout():
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError, io.UnsupportedOperation):
        pass


def main(argv=None):
    """Run the command line; return the exit status."""
    if argv is None:
        argv = sys.argv[1:]
        for stream in (sys.stdout, sys.stderr):
            try:
                stream.reconfigure(encoding="utf-8", newline="\n")
            except (AttributeError, ValueError):
                pass
    try:
        output = _run(list(argv))
    except _Exit as stop:
        try:
            sys.stderr.write(stop.message + "\n")
            sys.stderr.flush()
        except (BrokenPipeError, OSError):
            pass
        return stop.code
    try:
        sys.stdout.write(output)
        sys.stdout.flush()
    except BrokenPipeError:
        _quiet_stdout()
    return 0
