class Result:
    def __init__(self, code, out, err):
        self.code = code
        self.out = out
        self.err = err


class ShopTestCase(unittest.TestCase):
    """A temp folder holding the three files, and a way to run the CLI."""

    def setUp(self):
        self.dir = tempfile.mkdtemp(prefix="stockroom-test-")
        self.addCleanup(shutil.rmtree, self.dir, True)

    def write(self, name, content):
        data = content if isinstance(content, bytes) else content.encode("utf-8")
        with open(os.path.join(self.dir, name), "wb") as handle:
            handle.write(data)

    def read(self, name):
        with open(os.path.join(self.dir, name), "rb") as handle:
            return handle.read()

    def exists(self, name):
        return os.path.exists(os.path.join(self.dir, name))

    def shop(self, catalog=CATALOG, movements=MOVEMENTS, orders=ORDERS):
        if catalog is not None:
            self.write("catalog.txt", catalog)
        if movements is not None:
            self.write("movements.txt", movements)
        if orders is not None:
            self.write("orders.txt", orders)

    def run_cli(self, *args, dir=True):
        argv = list(args)
        if dir:
            argv = ["--dir", self.dir] + argv
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            code = cli.main(argv)
        return Result(code, out.getvalue(), err.getvalue())

    def assertRefused(self, result, code=1, text=None):
        self.assertEqual(result.code, code, result.err)
        self.assertEqual(result.out, "")
        self.assertTrue(result.err.strip(), "expected a message on stderr")
        if text is not None:
            self.assertIn(text, result.err)

    def run_process(self, *args, cwd=None, stdin_pipe=False):
        env = dict(os.environ, PYTHONPATH=SRC)
        return subprocess.run(
            [sys.executable, "-m", "stockroom"] + list(args),
            cwd=cwd or self.dir,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
